INSERT INTO `b2b_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2833, 343, '_лого', 'field_5b3e59ebc2a7c'),
(2834, 343, 'лого2', '293'),
(2835, 343, '_лого2', 'field_5b51a35453c05'),
